using System;
using System.Diagnostics;
using System.IO;
using System.IO.Pipes;
using System.Threading;
using System.Windows.Forms;
using Paster.Core;

namespace Paster.Windows
{
    internal sealed class ManagementPipe : IDisposable
    {
        private readonly PasterApplicationContext context; private readonly Thread thread; private readonly object pipeGate=new object(); private volatile bool stop; private NamedPipeServerStream activePipe;
        public ManagementPipe(PasterApplicationContext c) { context=c; thread=new Thread(Listen); thread.IsBackground=true; thread.Start(); }
        private void Listen() { while(!stop) { try { using(NamedPipeServerStream p=new NamedPipeServerStream("Paster.Management",PipeDirection.In,1,PipeTransmissionMode.Byte,PipeOptions.None)) { lock(pipeGate) { if(stop) return; activePipe=p; } try { p.WaitForConnection(); using(StreamReader r=new StreamReader(p)) { string command=r.ReadLine(); if(!String.IsNullOrEmpty(command)) context.DispatchCommand(command); } } finally { lock(pipeGate) { if(Object.ReferenceEquals(activePipe,p)) activePipe=null; } } } } catch { if(!stop) Thread.Sleep(100); } } }
        public void Dispose() { stop=true; lock(pipeGate) { if(activePipe!=null) { try { activePipe.Dispose(); } catch { } activePipe=null; } } if (thread != Thread.CurrentThread) thread.Join(); }
    }
    internal static class Management
    {
        public static bool TrySend(string arg, string ignored) { string command=arg.TrimStart('-').Replace("-", "-"); try { using(NamedPipeClientStream p=new NamedPipeClientStream(".","Paster.Management",PipeDirection.Out)) { p.Connect(300); using(StreamWriter w=new StreamWriter(p)) { w.AutoFlush=true; w.WriteLine(command); } } return true; } catch { return false; } }
        public static void SetAutostart(bool enabled) { string key="Software\\Microsoft\\Windows\\CurrentVersion\\Run"; using(Microsoft.Win32.RegistryKey k=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(key)) { if(enabled) k.SetValue("Paster", "\""+Application.ExecutablePath+"\" --background"); else k.DeleteValue("Paster", false); } }
        public static void ShowStatus(TransferCoordinator c) { TransferStatus s=c.Status; MessageBox.Show("Running\r\nCaptured text: "+(s.HasCapture?"yes":"no")+"\r\nTransfer active: "+(s.IsTransferring?"yes":"no")+"\r\nInput available: "+(s.IsInputAvailable?"yes":"no")+"\r\nTarget window: "+(s.TargetWindow==IntPtr.Zero?"none":s.TargetWindow.ToString())+"\r\nResume point: "+(s.ResumeOffset==0?"none":String.Format("{0:N0} of {1:N0} characters",s.ResumeOffset,s.ResumeTotal))+"\r\nLast error: "+(s.LastError??"none"),"Paster status"); }
        // Starts from the file's current contents so hand edits made while Paster runs are shown and kept, then applies the saved values live.
        public static void ShowSettings(PasterConfig live, string path) { PasterConfig c=PasterConfig.TryLoad(path) ?? live; using(Form f=new Form()) { f.Text="Paster settings"; f.Width=460; f.Height=760; f.FormBorderStyle=FormBorderStyle.FixedDialog; f.MaximizeBox=false; string[] labels={"Capture shortcut","Paste shortcut","Cancel shortcut","Start delay (ms)","Delay per batch (ms)","Characters per batch","Clipboard timeout (ms)","Maximum characters","Type on Ctrl+V in apps","Remote speed (keys/s, 0=max)","Confirm pastes over (lines, 0=never)","Prompt timeout (s)"}; TextBox[] boxes=new TextBox[12]; for(int i=0;i<labels.Length;i++){ Label l=new Label(); l.Text=labels[i]; l.Left=15;l.Top=15+i*34;l.Width=190; f.Controls.Add(l); boxes[i]=new TextBox(); boxes[i].Left=215;boxes[i].Top=l.Top-3;boxes[i].Width=200;f.Controls.Add(boxes[i]); } boxes[0].Text=c.CaptureShortcut;boxes[1].Text=c.PasteShortcut;boxes[2].Text=c.CancelShortcut;boxes[3].Text=c.StartDelayMilliseconds.ToString();boxes[4].Text=c.CharacterDelayMilliseconds.ToString();boxes[5].Text=c.CharactersPerBatch.ToString();boxes[6].Text=c.ClipboardTimeoutMilliseconds.ToString();boxes[7].Text=c.MaximumTextCharacters.ToString();boxes[8].Text=c.TypeOnPasteApps;boxes[9].Text=c.RemoteCharactersPerSecond.ToString();boxes[10].Text=c.ConfirmAboveLines.ToString();boxes[11].Text=c.PromptTimeoutSeconds.ToString(); string[] checkLabels={"Type on Ctrl+V in listed apps","Type text copied inside remote windows","Use code mode for Ctrl+V into remote windows","Shortcuts work in any key order","Type uppercase and symbols as Unicode (no Shift)","Stop typing on key press or click","Code mode: Escape before Enter and Tab","Code mode: Home after Enter","Code mode: Delete auto-closed brackets and quotes"}; bool[] checkValues={c.TypeOnCtrlV,c.TypeRemoteCopies,c.CodeModeForRemotePaste,c.AnyOrderShortcuts,c.TypeShiftedAsUnicode,c.StopOnUserInput,c.CodeModeEscapeBeforeEnter,c.CodeModeHomeAfterEnter,c.CodeModeDeleteAutoClosed}; CheckBox[] checks=new CheckBox[checkLabels.Length]; for(int i=0;i<checks.Length;i++){ checks[i]=new CheckBox(); checks[i].Text=checkLabels[i]; checks[i].Left=15; checks[i].Top=15+12*34+i*28; checks[i].Width=420; checks[i].Checked=checkValues[i]; f.Controls.Add(checks[i]); } Button save=new Button();save.Text="Save";save.Left=215;save.Top=685;save.DialogResult=DialogResult.OK;f.Controls.Add(save);f.AcceptButton=save; if(f.ShowDialog()==DialogResult.OK) try { PasterConfig candidate=c.Clone();candidate.CaptureShortcut=boxes[0].Text;candidate.PasteShortcut=boxes[1].Text;candidate.CancelShortcut=boxes[2].Text;candidate.StartDelayMilliseconds=Int32.Parse(boxes[3].Text);candidate.CharacterDelayMilliseconds=Int32.Parse(boxes[4].Text);candidate.CharactersPerBatch=Int32.Parse(boxes[5].Text);candidate.ClipboardTimeoutMilliseconds=Int32.Parse(boxes[6].Text);candidate.MaximumTextCharacters=Int32.Parse(boxes[7].Text);candidate.TypeOnPasteApps=boxes[8].Text.Trim();candidate.RemoteCharactersPerSecond=Int32.Parse(boxes[9].Text);candidate.ConfirmAboveLines=Int32.Parse(boxes[10].Text);candidate.PromptTimeoutSeconds=Int32.Parse(boxes[11].Text);candidate.TypeOnCtrlV=checks[0].Checked;candidate.TypeRemoteCopies=checks[1].Checked;candidate.CodeModeForRemotePaste=checks[2].Checked;candidate.AnyOrderShortcuts=checks[3].Checked;candidate.TypeShiftedAsUnicode=checks[4].Checked;candidate.StopOnUserInput=checks[5].Checked;candidate.CodeModeEscapeBeforeEnter=checks[6].Checked;candidate.CodeModeHomeAfterEnter=checks[7].Checked;candidate.CodeModeDeleteAutoClosed=checks[8].Checked;candidate.Save(path);live.CopyFrom(candidate); MessageBox.Show("Saved. Restart Paster for shortcut changes.","Paster"); } catch(Exception ex) { MessageBox.Show(ex.Message,"Invalid settings"); } } }
    }
}
